   960  static void setup_chunked(struct st_h2o_http1_finalostream_t *self, h2o_req_t *req)
   961  {
   962      if (should_use_chunked_encoding(req)) {
   963          h2o_add_header(&req->pool, &req->res.headers, H2O_TOKEN_TRANSFER_ENCODING, NULL, H2O_STRLIT("chunked"));
   964          self->chunked_buf = h2o_mem_alloc_pool_aligned(&req->pool, 1, sizeof(size_t) * 2 + sizeof("\r\n"));
   965      }
   966  }
