   968  static void encode_chunked(h2o_sendvec_t *prefix, h2o_sendvec_t *suffix, h2o_send_state_t state, size_t chunk_size,
   969                             int send_trailers, char *buffer)
   970  {
   971      h2o_sendvec_init_raw(prefix, NULL, 0);
   972      h2o_sendvec_init_raw(suffix, NULL, 0);
   973
   974      /* create chunk header and output data */
   975      if (chunk_size != 0) {
   976          prefix->raw = buffer;
   977          prefix->len = sprintf(buffer, "%zx\r\n", chunk_size);
   978          if (state != H2O_SEND_STATE_ERROR) {
   979              suffix->raw = "\r\n0\r\n\r\n";
   980              suffix->len = state == H2O_SEND_STATE_FINAL ? (send_trailers ? 5 : 7) : 2;
   981          }
   982      } else if (state == H2O_SEND_STATE_FINAL) {
   983          suffix->raw = "0\r\n\r\n";
   984          suffix->len = send_trailers ? 3 : 5;
   985      }
   986
   987      /* if state is error, send a broken chunk to pass the error down to the browser */
   988      if (state == H2O_SEND_STATE_ERROR) {
   989          suffix->raw = "\r\n1\r\n";
   990          suffix->len = 5;
   991      }
   992  }
